1243	fn selectionScrollTick(self: *Surface) !void {
1244	    // If we're no longer active then we don't do anything.
1245	    if (!self.selection_scroll_active) return;
1246	
1247	    // If our gesture doesn't want autoscrolling then disable it.
1248	    const was_autoscrolling = self.mouse.selection_gesture.left_drag_autoscroll != .none;
1249	    if (!was_autoscrolling) {
1250	        self.queueIo(
1251	            .{ .selection_scroll = false },
1252	            .unlocked,
1253	        );
1254	        return;
1255	    }
1256	
1257	    const pos = try self.rt_surface.getCursorPos();
1258	    const pos_vp = self.posToViewport(pos.x, pos.y);
1259	
1260	    // We need our locked state for the remainder
1261	    self.renderer_state.mutex.lockUncancelable(global.io());
1262	    defer self.renderer_state.mutex.unlock(global.io());
1263	    const t: *terminal.Terminal = self.renderer_state.terminal;
1264	
1265	    const selection = self.mouse.selection_gesture.autoscrollTick(t, .{
1266	        .viewport = pos_vp,
1267	        .xpos = pos.x,
1268	        .ypos = pos.y,
1269	        .rectangle = SurfaceMouse.isRectangleSelectState(self.mouse.mods),
1270	        .word_boundary_codepoints = self.config.selection_word_chars,
